package com.reactnativeexamples

import android.content.Context
import android.os.Build
import android.util.Log
import com.facebook.react.bridge.Arguments
import com.facebook.react.bridge.Promise
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.bridge.WritableArray
import com.facebook.react.bridge.WritableMap
import com.reactnativeexamples.specs.NativeTodosSpec
import java.text.Normalizer
import org.json.JSONArray
import org.json.JSONObject

/**
 * Turbo Native Module that stores the todos in SharedPreferences.
 *
 * NativeTodosSpec is generated by Codegen from specs/NativeTodos.ts during the
 * Gradle build (android/app/build/generated/source/codegen). Each abstract
 * method there matches a method of the spec, so if the spec and this class
 * disagree, the app doesn't compile.
 *
 * The list is kept in memory and saved as one JSON string under the key
 * "todos" of the "native_todos" preferences file:
 * /data/data/com.reactnativeexamples/shared_prefs/native_todos.xml
 */
class NativeTodosModule(reactContext: ReactApplicationContext) :
  NativeTodosSpec(reactContext) {

  private data class Todo(
    val id: String,
    val text: String,
    val date: Double,
    val completed: Boolean,
  )

  private val prefs =
    reactContext.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)

  // Async methods run on a background thread and sync ones on the JS thread,
  // so every access to the list goes through this lock.
  private val lock = Any()
  private var todos: MutableList<Todo>? = null

  override fun getName() = NAME

  // ---------------------------------------------------------------------
  // Async methods (Promise in the spec → Promise parameter here)
  // ---------------------------------------------------------------------

  override fun getAll(promise: Promise) {
    promise.resolve(toArray(synchronized(lock) { load().toList() }))
  }

  override fun search(query: String, promise: Promise) {
    val needle = normalize(query.trim())
    val found = synchronized(lock) {
      load().filter { normalize(it.text).contains(needle) }
    }
    Log.d(TAG, "search(\"$query\") → ${found.size} result(s)")
    promise.resolve(toArray(found))
  }

  override fun add(text: String, date: Double, completed: Boolean, promise: Promise) {
    if (text.isBlank()) {
      promise.reject("E_EMPTY_TEXT", "The todo text can't be empty")
      return
    }
    val todo = synchronized(lock) {
      val id = prefs.getLong(KEY_NEXT_ID, 1L)
      val created = Todo(id.toString(), text.trim(), date, completed)
      load().add(created)
      save(nextId = id + 1)
      created
    }
    Log.d(TAG, "add → id ${todo.id}")
    promise.resolve(toMap(todo))
  }

  override fun update(
    todoId: String,
    text: String?,
    date: Double?,
    completed: Boolean?,
    promise: Promise,
  ) {
    val updated = synchronized(lock) {
      val list = load()
      val index = list.indexOfFirst { it.id == todoId }
      if (index == -1) {
        null
      } else {
        val current = list[index]
        // null means "don't change this field".
        val changed = current.copy(
          text = text?.trim() ?: current.text,
          date = date ?: current.date,
          completed = completed ?: current.completed,
        )
        list[index] = changed
        save()
        changed
      }
    }
    if (updated == null) {
      promise.reject("E_NOT_FOUND", "No todo with id $todoId")
    } else {
      promise.resolve(toMap(updated))
    }
  }

  override fun remove(todoId: String, promise: Promise) {
    val removed = synchronized(lock) {
      val didRemove = load().removeAll { it.id == todoId }
      if (didRemove) save()
      didRemove
    }
    promise.resolve(removed)
  }

  override fun clear(promise: Promise) {
    synchronized(lock) {
      load().clear()
      save()
    }
    promise.resolve(null)
  }

  // ---------------------------------------------------------------------
  // Sync methods (plain return value in the spec → plain return value here)
  // ---------------------------------------------------------------------

  override fun count(): Double = synchronized(lock) { load().size.toDouble() }

  override fun getInfo(): WritableMap =
    Arguments.createMap().apply {
      putString("platform", "Android ${Build.VERSION.RELEASE} (Kotlin)")
      putString("storage", "SharedPreferences \"$PREFS_NAME\"")
      putString("key", KEY_TODOS)
    }

  // ---------------------------------------------------------------------
  // Storage
  // ---------------------------------------------------------------------

  /** Reads the JSON from SharedPreferences the first time; then uses memory. */
  private fun load(): MutableList<Todo> {
    todos?.let { return it }
    val json = JSONArray(prefs.getString(KEY_TODOS, "[]"))
    val list = MutableList(json.length()) { i ->
      val item = json.getJSONObject(i)
      Todo(
        id = item.getString("id"),
        text = item.getString("text"),
        date = item.getDouble("date"),
        completed = item.getBoolean("completed"),
      )
    }
    todos = list
    return list
  }

  private fun save(nextId: Long? = null) {
    val json = JSONArray()
    load().forEach {
      json.put(
        JSONObject()
          .put("id", it.id)
          .put("text", it.text)
          .put("date", it.date)
          .put("completed", it.completed),
      )
    }
    prefs.edit().apply {
      putString(KEY_TODOS, json.toString())
      if (nextId != null) putLong(KEY_NEXT_ID, nextId)
      apply() // writes to disk in the background
    }
  }

  // ---------------------------------------------------------------------
  // Conversions to JS values
  // ---------------------------------------------------------------------

  private fun toMap(todo: Todo): WritableMap =
    Arguments.createMap().apply {
      putString("id", todo.id)
      putString("text", todo.text)
      putDouble("date", todo.date)
      putBoolean("completed", todo.completed)
    }

  private fun toArray(list: List<Todo>): WritableArray =
    Arguments.createArray().apply { list.forEach { pushMap(toMap(it)) } }

  /** Lowercase without accents, so "cafe" finds "Café". */
  private fun normalize(value: String): String =
    Normalizer.normalize(value, Normalizer.Form.NFD)
      .replace(DIACRITICS, "")
      .lowercase()

  companion object {
    /** Must match TurboModuleRegistry.get('NativeTodos') in the spec. */
    const val NAME = "NativeTodos"
    private const val TAG = "NativeTodos"
    private const val PREFS_NAME = "native_todos"
    private const val KEY_TODOS = "todos"
    private const val KEY_NEXT_ID = "next_id"
    private val DIACRITICS = Regex("\\p{Mn}+")
  }
}
